from pathlib import Path
p=Path('app/src/androidTest/java/kr/yunseok/touchmacro/PxeRedesignTest.java');s=p.read_text(encoding='utf-8');s=s.replace('    void targets(View root)', '''    View marker(){try{java.lang.reflect.Field f=FloatingController.class.getDeclaredField("markers");f.setAccessible(true);java.util.List<?> views=(java.util.List<?>)f.get(h.svc.controller());assertFalse(views.isEmpty());return (View)views.get(0);}catch(Exception e){throw new RuntimeException(e);}}
    void markerCenter(double tolerance){View marker=marker();Rect bounds=h.bounds(marker);Step saved=Store.load(h.a).steps.get(0);int[] size=h.svc.size();assertEquals("표시와 저장 X 중심",saved.x*size[0]/100,bounds.exactCenterX(),tolerance);assertEquals("표시와 저장 Y 중심",saved.y*size[1]/100,bounds.exactCenterY(),tolerance);}
    void targets(View root)''')
s=s.replace('Ui.prefs(h.a).edit().putInt("scale",100).commit();h.svc.controller().show();','Ui.prefs(h.a).edit().putInt("scale",100).putBoolean("markers",true).commit();Macro m=new Macro();Step tap=new Step("TAP");tap.x=50;tap.y=50;m.steps.add(tap);Store.save(h.a,m);h.svc.controller().show();')
s=s.replace('h.main(()->targets(privateView(h.svc.controller(),"panel")));h.screenshot("PXE14_제어창_펼침.png");', '''h.main(()->{targets(privateView(h.svc.controller(),"panel"));targets(marker());markerCenter(.51);});h.screenshot("PXE14_제어창_펼침.png");final Rect[] before={null};h.main(()->before[0]=h.bounds(marker()));h.drag(before[0].exactCenterX(),before[0].exactCenterY(),before[0].exactCenterX()+100,before[0].exactCenterY()-80);h.in.waitForIdleSync();h.main(()->{markerCenter(.000001);Step saved=Store.load(h.a).steps.get(0);assertTrue(saved.x>50);assertTrue(saved.y<50);});h.screenshot("PXE14_번호점_이동.png");''')
p.write_text(s,encoding='utf-8')
